from collections import defaultdict
class AuctionSystem:
    def __init__(self):
        self.d = defaultdict(dict)
    def addBid(self, userId, itemId, bidAmount):
        self.d[itemId][userId] = bidAmount
    def updateBid(self, userId, itemId, newAmount):
        self.d[itemId][userId] = newAmount
    def removeBid(self, userId, itemId):
        self.d[itemId].pop(userId, None)
    def getHighestBidder(self, itemId):
        best, ba = -1, -1
        for u, a in self.d[itemId].items():
            if a > ba or (a == ba and u > best):
                best, ba = u, a
        return best

