public:
    void addBid(int u, int i, int a) { d[i][u] = a; }
    void updateBid(int u, int i, int a) { d[i][u] = a; }
    void removeBid(int u, int i) { d[i].erase(u); }
    int getHighestBidder(int i) {
        int best = -1, ba = -1;
        for (auto& [u, a] : d[i])
            if (a > ba || (a == ba && u > best)) { best = u; ba = a; }
        return best;
    }
