class AuctionSystem {
    private Map<Integer, HashMap<Integer,Integer>> d = new HashMap<>();
    public void addBid(int u, int i, int a) { d.computeIfAbsent(i, k -> new HashMap<>()).put(u, a); }
    public void updateBid(int u, int i, int a) { addBid(u, i, a); }
    public void removeBid(int u, int i) { HashMap<Integer,Integer> m = d.get(i); if (m != null) m.remove(u); }
    public int getHighestBidder(int i) {
        HashMap<Integer,Integer> m = d.get(i);
        if (m == null) return -1;
        int best = -1, ba = -1;
        for (Map.Entry<Integer,Integer> e : m.entrySet()) {
            int u = e.getKey(), a = e.getValue();
            if (a > ba || (a == ba && u > best)) { best = u; ba = a; }
        }
        return best;
    }
}

