import heapq
from collections import defaultdict
class AuctionSystem:
    def __init__(self):
        self.bid = {}
        self.h = defaultdict(list)
    def addBid(self, userId, itemId, bidAmount):
        self.bid[(userId, itemId)] = bidAmount
        heapq.heappush(self.h[itemId], (-bidAmount, -userId))
    def updateBid(self, userId, itemId, newAmount):
        self.addBid(userId, itemId, newAmount)
    def removeBid(self, userId, itemId):
        self.bid.pop((userId, itemId), None)
    def getHighestBidder(self, itemId):
        h = self.h[itemId]
        while h:
            a, u = -h[0]
            if self.bid.get((u, itemId)) == a:
                return u
            heapq.heappop(h)
        return -1

