class AuctionSystem {
    unordered_map<long long,int> bid;
    unordered_map<int, priority_queue<pair<int,int>>> h;
    long long key(long long u, long long i) { return u * 100000LL + i; }
public:
    void addBid(int u, int i, int a) {
        bid[key(u, i)] = a;
        h[i].push({a, u});
    }
    void updateBid(int u, int i, int a) { addBid(u, i, a); }
    void removeBid(int u, int i) { bid.erase(key(u, i)); }
    int getHighestBidder(int i) {
        auto& q = h[i];
        while (!q.empty()) {
            auto [a, u] = q.top();
            auto it = bid.find(key(u, i));
            if (it != bid.end() && it->second == a) return u;
            q.pop();
        }
        return -1;
    }
};

