class AuctionSystem {
    private Map<Long,Integer> bid = new HashMap<>();
    private Map<Integer, PriorityQueue<long[]>> h = new HashMap<>();
    private long key(long u, long i) { return u * 100000L + i; }
    public void addBid(int u, int i, int a) {
        bid.put(key(u, i), a);
        h.computeIfAbsent(i, k -> new PriorityQueue<>((x, y) ->
            x[0] != y[0] ? Long.compare(y[0], x[0]) : Long.compare(y[1], x[1]))
        ).add(new long[]{a, u});
    }
    public void updateBid(int u, int i, int a) { addBid(u, i, a); }
    public void removeBid(int u, int i) { bid.remove(key(u, i)); }
    public int getHighestBidder(int i) {
        PriorityQueue<long[]> q = h.get(i);
        if (q == null) return -1;
        while (!q.isEmpty()) {
            long[] t = q.peek();
            Integer v = bid.get(key(t[1], i));
            if (v != null && v.longValue() == t[0]) return (int) t[1];
            q.poll();
        }
        return -1;
    }
}

