function hpush(h, e) {
    h.push(e); let i = h.length - 1;
    while (i > 0) {
        const p = (i - 1) >> 1;
        if (h[p][0] > h[i][0] || (h[p][0] === h[i][0] && h[p][1] >= h[i][1])) break;
        [h[p], h[i]] = [h[i], h[p]]; i = p;
    }
}
function hpop(h) {
    const t = h[0], l = h.pop();
    if (h.length) {
        h[0] = l; let i = 0;
        for (;;) {
            const a = 2 * i + 1, b = a + 1; let m = i;
            if (a < h.length && (h[a][0] > h[m][0] || (h[a][0] === h[m][0] && h[a][1] > h[m][1]))) m = a;
            if (b < h.length && (h[b][0] > h[m][0] || (h[b][0] === h[m][0] && h[b][1] > h[m][1]))) m = b;
            if (m === i) break;
            [h[m], h[i]] = [h[i], h[m]]; i = m;
        }
    }
    return t;
}
var AuctionSystem = function() { this.bid = new Map(); this.h = new Map(); };
AuctionSystem.prototype.addBid = function(u, i, a) {
    this.bid.set(u + '_' + i, a);
    if (!this.h.has(i)) this.h.set(i, []);
    hpush(this.h.get(i), [a, u]);
};
AuctionSystem.prototype.updateBid = function(u, i, a) { this.addBid(u, i, a); };
AuctionSystem.prototype.removeBid = function(u, i) { this.bid.delete(u + '_' + i); };
AuctionSystem.prototype.getHighestBidder = function(i) {
    const h = this.h.get(i) || [];
    while (h.length) {
        const t = h[0];
        if (this.bid.get(t[1] + '_' + i) === t[0]) return t[1];
        hpop(h);
    }
    return -1;
};
